import { AlertTriangle, GitBranch, Trash2, X } from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import {
  DEFAULT_WORKSPACE_ID,
  deleteWorktree,
  deleteWorktreeDestructive,
  previewWorktreeDelete,
  toIpcError,
} from "../lib/tauri";
import { worktreeIdentity, type BranchDeletionPreview, type StructuredIpcError, type Worktree } from "../lib/types";

export type WorktreeDeleteServices = {
  previewDelete: (worktree: Worktree) => Promise<BranchDeletionPreview>;
  deleteSafe: (worktree: Worktree) => Promise<void>;
  deleteDestructive: (worktree: Worktree) => Promise<void>;
};

type WorktreeDeleteDialogProps = {
  workspaceId?: string;
  worktree: Worktree;
  onClose: () => void;
  onDeleted: () => void;
  services?: WorktreeDeleteServices;
};

function createDefaultServices(workspaceId: string): WorktreeDeleteServices {
  return {
    previewDelete: async (worktree) => {
      const identity = requireIdentity(worktree);
      return previewWorktreeDelete({ workspaceId, worktree: identity });
    },
    deleteSafe: async (worktree) => {
      const identity = requireIdentity(worktree);
      await deleteWorktree({ workspaceId, worktree: identity, deleteBranch: true });
    },
    deleteDestructive: async (worktree) => {
      const identity = requireIdentity(worktree);
      await deleteWorktreeDestructive({ workspaceId, worktree: identity, deleteBranch: true });
    },
  };
}

export function WorktreeDeleteDialog({
  workspaceId = DEFAULT_WORKSPACE_ID,
  worktree,
  onClose,
  onDeleted,
  services,
}: WorktreeDeleteDialogProps) {
  const resolvedServices = useMemo(() => services ?? createDefaultServices(workspaceId), [services, workspaceId]);
  const [preview, setPreview] = useState<BranchDeletionPreview | null>(null);
  const [error, setError] = useState<StructuredIpcError | null>(null);
  const [destructiveRequired, setDestructiveRequired] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setPreview(null);
    setError(null);
    setDestructiveRequired(false);
    setBusy(true);
    void resolvedServices
      .previewDelete(worktree)
      .then((result) => {
        if (!cancelled) setPreview(result);
      })
      .catch((cause) => {
        if (!cancelled) setError(toIpcError(cause));
      })
      .finally(() => {
        if (!cancelled) setBusy(false);
      });
    return () => {
      cancelled = true;
    };
  }, [resolvedServices, worktree]);

  const finishDelete = () => {
    onDeleted();
    onClose();
  };

  const handleSafeDelete = async () => {
    setBusy(true);
    setError(null);
    try {
      await resolvedServices.deleteSafe(worktree);
      finishDelete();
    } catch (cause) {
      const ipcError = toIpcError(cause);
      setError(ipcError);
      setDestructiveRequired(ipcError.code === "UNMERGED_BRANCH");
    } finally {
      setBusy(false);
    }
  };

  const handleDestructiveDelete = async () => {
    setBusy(true);
    setError(null);
    try {
      await resolvedServices.deleteDestructive(worktree);
      finishDelete();
    } catch (cause) {
      setError(toIpcError(cause));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm" onMouseDown={onClose}>
      <div
        role="dialog"
        aria-label="Delete worktree"
        aria-modal="true"
        className="w-full max-w-lg animate-enter overflow-hidden rounded-xl border border-border bg-card shadow-2xl"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <header className="flex items-center justify-between border-b border-border px-4 py-3">
          <div className="flex items-center gap-2 text-sm font-semibold text-foreground">
            <Trash2 className="size-4 text-destructive" />
            Delete worktree
          </div>
          <button type="button" onClick={onClose} aria-label="Close delete dialog" className="rounded-md p-1 text-muted-foreground hover:bg-accent hover:text-foreground">
            <X className="size-4" />
          </button>
        </header>

        <div className="space-y-4 p-4 text-xs">
          <p className="text-muted-foreground">
            Review the branch state before deleting <span className="font-mono text-foreground">{worktree.path}</span>.
          </p>

          {busy && !preview ? <div className="rounded-md border border-border bg-background/50 px-3 py-4 text-muted-foreground">Loading deletion preview…</div> : null}

          {preview ? (
            <div className="overflow-hidden rounded-lg border border-border bg-background/45">
              <PreviewRow label="Branch" value={preview.branch} icon={<GitBranch className="size-3" />} />
              <PreviewRow label="HEAD" value={preview.head} mono />
              <PreviewRow label="Upstream" value={preview.upstream ?? "None"} />
              <PreviewRow label="Merge state" value={preview.merged ? "Merged" : "Not merged"} />
              <PreviewRow label="Divergence" value={`${preview.ahead ?? "?"} ahead · ${preview.behind ?? "?"} behind`} />
            </div>
          ) : null}

          {destructiveRequired ? (
            <div className="space-y-2 rounded-lg border border-destructive/35 bg-destructive/10 p-3">
              <div className="flex items-start gap-2 text-destructive">
                <AlertTriangle className="mt-0.5 size-4 shrink-0" />
                <div>
                  <div className="font-semibold">Unmerged branch</div>
                  <p className="mt-1 text-[11px] leading-relaxed text-destructive/85">
                    Safe deletion refused to discard unmerged commits. Destructive deletion is a separate explicit action.
                  </p>
                </div>
              </div>
              <button
                type="button"
                disabled={busy}
                onClick={() => void handleDestructiveDelete()}
                className="w-full rounded-md bg-destructive px-3 py-2 font-semibold text-destructive-foreground disabled:opacity-50"
              >
                Delete unmerged branch permanently
              </button>
            </div>
          ) : null}

          {error && !destructiveRequired ? (
            <div className="rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-destructive">
              <div className="font-semibold">{error.code}</div>
              <div className="mt-0.5 text-[11px]">{error.message}</div>
            </div>
          ) : null}

          <div className="flex justify-end gap-2">
            <button type="button" onClick={onClose} className="rounded-md px-3 py-2 text-muted-foreground hover:bg-accent hover:text-foreground">
              Cancel
            </button>
            {!destructiveRequired ? (
              <button
                type="button"
                disabled={busy || !preview}
                onClick={() => void handleSafeDelete()}
                className="rounded-md bg-destructive px-3 py-2 font-semibold text-destructive-foreground disabled:opacity-50"
              >
                Delete worktree and branch
              </button>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
}

function PreviewRow({ label, value, mono = false, icon }: { label: string; value: string; mono?: boolean; icon?: React.ReactNode }) {
  return (
    <div className="flex items-center gap-3 border-b border-border px-3 py-2 last:border-b-0">
      <span className="flex w-24 shrink-0 items-center gap-1 text-muted-foreground">{icon}{label}</span>
      <span className={`min-w-0 flex-1 truncate text-right text-foreground ${mono ? "font-mono" : ""}`}>{value}</span>
    </div>
  );
}

function requireIdentity(worktree: Worktree) {
  const identity = worktreeIdentity(worktree);
  if (identity) return identity;
  throw {
    code: "INVALID_NAMESPACE",
    message: "Only Ferryx-managed worktrees can be deleted from this UI.",
    details: { path: worktree.path },
  } satisfies StructuredIpcError;
}

use crate::ipc::{run_blocking, IpcError};
use crate::worktree::{
    BranchDeletionPreview, CreateWorktreeOptions, DirtyState, Worktree, WorktreeIdentity,
    WorkspaceRegistry,
};
use serde::{Deserialize, Serialize};
use tauri::{AppHandle, Emitter, Runtime, State};

pub const WORKTREE_CHANGED_EVENT: &str = "worktree_changed";

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct CreateWorktreeRequest {
    pub workspace_id: String,
    pub worktree: WorktreeIdentity,
    pub base_ref: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct DeleteWorktreeRequest {
    pub workspace_id: String,
    pub worktree: WorktreeIdentity,
    pub delete_branch: Option<bool>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct WorktreeStatusRequest {
    pub workspace_id: String,
    pub worktree: WorktreeIdentity,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum WorktreeChangeKind {
    Created,
    Deleted,
    DestructivelyDeleted,
    #[serde(rename = "dirtyChanged")]
    DirtyChanged,
    Pruned,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WorktreeChangedPayload {
    pub workspace_id: String,
    pub worktree: WorktreeIdentity,
    pub kind: WorktreeChangeKind,
}

fn emit_worktree_changed<R: Runtime>(
    app: &AppHandle<R>,
    workspace_id: String,
    worktree: WorktreeIdentity,
    kind: WorktreeChangeKind,
) -> Result<(), IpcError> {
    app.emit(
        WORKTREE_CHANGED_EVENT,
        WorktreeChangedPayload {
            workspace_id,
            worktree,
            kind,
        },
    )
    .map_err(|error| IpcError::internal(format!("failed to emit worktree_changed: {error}")))
}

#[tauri::command]
pub async fn cmd_worktree_list(
    registry: State<'_, WorkspaceRegistry>,
    workspace_id: String,
) -> Result<Vec<Worktree>, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        let manager = registry.manager(&workspace_id).map_err(IpcError::from)?;
        manager.list_worktrees().map_err(IpcError::from)
    })
    .await
}

#[tauri::command]
pub async fn cmd_worktree_create<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: CreateWorktreeRequest,
) -> Result<Worktree, IpcError> {
    let registry = (*registry).clone();
    let workspace_id = request.workspace_id.clone();
    let identity = request.worktree.clone();
    let event_workspace_id = workspace_id.clone();
    let event_identity = identity.clone();

    let created = run_blocking(move || {
        let manager = registry.manager(&workspace_id).map_err(IpcError::from)?;
        let target = manager
            .worktree_path_for(&identity.ws_id, &identity.slug)
            .map_err(IpcError::from)?;
        let mut options =
            CreateWorktreeOptions::new(identity.ws_id.clone(), identity.slug.clone(), target);
        if let Some(base_ref) = request.base_ref {
            options = options.with_base_ref(base_ref);
        }
        manager.create_worktree(options).map_err(IpcError::from)
    })
    .await?;

    emit_worktree_changed(
        &app,
        event_workspace_id,
        event_identity,
        WorktreeChangeKind::Created,
    )?;
    Ok(created)
}

async fn delete_worktree<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: DeleteWorktreeRequest,
    destructive: bool,
) -> Result<(), IpcError> {
    let registry = (*registry).clone();
    let workspace_id = request.workspace_id.clone();
    let identity = request.worktree.clone();
    let delete_branch = request.delete_branch.unwrap_or(false);
    let event_workspace_id = workspace_id.clone();
    let event_identity = identity.clone();

    let pruned = run_blocking(move || {
        let (manager, worktree) = registry
            .resolve_worktree(&workspace_id, &identity)
            .map_err(IpcError::from)?;
        manager
            .delete_worktree_and_branch_with_prune_status(
                &worktree.path,
                delete_branch,
                destructive,
            )
            .map_err(IpcError::from)
    })
    .await?;

    emit_worktree_changed(
        &app,
        event_workspace_id.clone(),
        event_identity.clone(),
        if destructive {
            WorktreeChangeKind::DestructivelyDeleted
        } else {
            WorktreeChangeKind::Deleted
        },
    )?;
    if pruned {
        emit_worktree_changed(
            &app,
            event_workspace_id,
            event_identity,
            WorktreeChangeKind::Pruned,
        )?;
    }
    Ok(())
}

#[tauri::command]
pub async fn cmd_worktree_delete<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: DeleteWorktreeRequest,
) -> Result<(), IpcError> {
    delete_worktree(app, registry, request, false).await
}

#[tauri::command]
pub async fn cmd_worktree_delete_destructive<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: DeleteWorktreeRequest,
) -> Result<(), IpcError> {
    delete_worktree(app, registry, request, true).await
}

#[tauri::command]
pub async fn cmd_worktree_delete_preview(
    registry: State<'_, WorkspaceRegistry>,
    request: WorktreeStatusRequest,
) -> Result<BranchDeletionPreview, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        let (manager, worktree) = registry
            .resolve_worktree(&request.workspace_id, &request.worktree)
            .map_err(IpcError::from)?;
        manager
            .branch_deletion_preview(&worktree.path)
            .map_err(IpcError::from)
    })
    .await
}

#[tauri::command]
pub async fn cmd_worktree_status<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: WorktreeStatusRequest,
) -> Result<DirtyState, IpcError> {
    let registry = (*registry).clone();
    let workspace_id = request.workspace_id.clone();
    let identity = request.worktree.clone();
    let event_workspace_id = workspace_id.clone();
    let event_identity = identity.clone();

    let (status, changed) = run_blocking(move || {
        let (manager, worktree) = registry
            .resolve_worktree(&workspace_id, &identity)
            .map_err(IpcError::from)?;
        manager
            .observe_dirty_state(&worktree.path)
            .map_err(IpcError::from)
    })
    .await?;

    if changed {
        emit_worktree_changed(
            &app,
            event_workspace_id,
            event_identity,
            WorktreeChangeKind::DirtyChanged,
        )?;
    }
    Ok(status)
}

use ferryx_lib::terminal::PtyManager;
use ferryx_lib::worktree::{CreateWorktreeOptions, WorktreeError, WorktreeManager};
use portable_pty::CommandBuilder;
use std::fs;
use std::time::Duration;
use tempfile::TempDir;

fn setup_test_repo() -> (TempDir, WorktreeManager) {
    let temp_dir = TempDir::new().expect("temp dir");
    let repo_path = temp_dir.path();
    ferryx_lib::worktree::run_git(repo_path, &["init"]).expect("git init");
    ferryx_lib::worktree::run_git(repo_path, &["config", "user.name", "Orca Test"])
        .expect("git user name");
    ferryx_lib::worktree::run_git(repo_path, &["config", "user.email", "test@orca.dev"])
        .expect("git user email");
    fs::write(repo_path.join("README.md"), "# base\n").expect("write base");
    ferryx_lib::worktree::run_git(repo_path, &["add", "README.md"]).expect("git add");
    ferryx_lib::worktree::run_git(repo_path, &["commit", "-m", "base"]).expect("git commit");
    let manager = WorktreeManager::new(repo_path);
    (temp_dir, manager)
}

fn create_worktree(manager: &WorktreeManager, slug: &str) -> std::path::PathBuf {
    let path = manager.repo_root().join(format!("wt-{slug}"));
    manager
        .create_worktree(CreateWorktreeOptions::new("ws-safety", slug, &path))
        .expect("create worktree");
    path
}

#[test]
fn second_writer_is_rejected_and_release_allows_reacquire() {
    let (_repo, manager) = setup_test_repo();
    let wt = create_worktree(&manager, "lease");

    manager.acquire_writer(&wt, "owner-a").expect("first writer");
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), Some("owner-a".into()));

    let err = manager.acquire_writer(&wt, "owner-b").unwrap_err();
    assert!(matches!(err, WorktreeError::WriterAlreadyActive { .. }));

    manager.release_writer(&wt, "owner-a").expect("release owner-a");
    manager.acquire_writer(&wt, "owner-b").expect("owner-b reacquire");
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), Some("owner-b".into()));
    manager.release_writer(&wt, "owner-b").expect("release owner-b");
}

#[test]
fn active_writer_blocks_delete() {
    let (_repo, manager) = setup_test_repo();
    let wt = create_worktree(&manager, "active-writer");

    manager.acquire_writer(&wt, "agent-1").expect("writer acquire");
    let err = manager.safe_delete(&wt).unwrap_err();
    assert!(matches!(err, WorktreeError::WriterAlreadyActive { .. }));
    assert!(wt.exists(), "active writer worktree must remain");
    manager.release_writer(&wt, "agent-1").expect("writer release");
}

#[test]
fn default_delete_rejects_clean_unmerged_branch() {
    let (_repo, manager) = setup_test_repo();
    let wt = create_worktree(&manager, "unmerged-default");

    fs::write(wt.join("feature.txt"), "unmerged work\n").expect("write feature");
    ferryx_lib::worktree::run_git(&wt, &["add", "feature.txt"]).expect("git add");
    ferryx_lib::worktree::run_git(&wt, &["commit", "-m", "unmerged feature"])
        .expect("feature commit");
    assert!(!manager.is_dirty(&wt).expect("clean status"));

    let err = manager.delete_worktree_and_branch(&wt, true).unwrap_err();
    assert!(matches!(err, WorktreeError::UnmergedBranch { .. }));
    assert!(wt.exists(), "default delete must preserve unmerged worktree");
    let branches = ferryx_lib::worktree::run_git(manager.repo_root(), &["branch", "--list"])
        .expect("list branches");
    assert!(branches.contains("orca/ws-safety/unmerged-default"));
}

#[test]
fn explicit_destructive_delete_removes_clean_unmerged_branch() {
    let (_repo, manager) = setup_test_repo();
    let wt = create_worktree(&manager, "unmerged-force");

    fs::write(wt.join("feature.txt"), "unmerged work\n").expect("write feature");
    ferryx_lib::worktree::run_git(&wt, &["add", "feature.txt"]).expect("git add");
    ferryx_lib::worktree::run_git(&wt, &["commit", "-m", "unmerged feature"])
        .expect("feature commit");

    let preview = manager
        .branch_deletion_preview(&wt)
        .expect("destructive preview");
    assert_eq!(preview.branch, "orca/ws-safety/unmerged-force");
    assert!(!preview.head.is_empty());
    assert!(!preview.merged);

    manager
        .delete_worktree_and_branch_destructive(&wt, true)
        .expect("explicit destructive delete");
    assert!(!wt.exists());
    let branches = ferryx_lib::worktree::run_git(manager.repo_root(), &["branch", "--list"])
        .expect("list branches");
    assert!(!branches.contains("orca/ws-safety/unmerged-force"));
}

#[tokio::test]
async fn same_worktree_supports_multiple_interactive_pty_sessions() {
    let (_repo, manager) = setup_test_repo();
    let wt = create_worktree(&manager, "multi-pty");
    let canonical = fs::canonicalize(&wt).expect("canonical worktree");
    let pty = PtyManager::new();

    let mut first_shell = CommandBuilder::new("/bin/sh");
    first_shell.cwd(&wt);
    let (first_id, _first_rx) = pty
        .spawn_in_worktree(first_shell, 80, 24, &manager, &wt)
        .expect("spawn first terminal");

    let mut second_shell = CommandBuilder::new("/bin/sh");
    second_shell.cwd(&wt);
    let (second_id, _second_rx) = pty
        .spawn_in_worktree(second_shell, 80, 24, &manager, &wt)
        .expect("spawn second terminal in same worktree");

    assert_ne!(first_id, second_id);
    assert_eq!(pty.session_count(), 2);
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), None);
    assert_eq!(pty.get_session(&first_id).and_then(|session| session.worktree_path()), Some(canonical.clone()));
    assert_eq!(pty.get_session(&second_id).and_then(|session| session.worktree_path()), Some(canonical));

    pty.close_session(&first_id).await.expect("close first terminal");
    assert!(pty.has_session(&second_id), "closing one split PTY must not close its sibling");
    pty.close_session(&second_id).await.expect("close second terminal");
    assert_eq!(pty.session_count(), 0);
}

#[tokio::test]
async fn pty_worktree_ownership_clears_on_close_and_natural_exit() {
    let (_repo, manager) = setup_test_repo();
    let wt = create_worktree(&manager, "pty-ownership");
    let pty = PtyManager::new();

    let mut shell = CommandBuilder::new("/bin/sh");
    shell.cwd(&wt);
    let (session_id, _rx) = pty
        .spawn_in_worktree(shell, 80, 24, &manager, &wt)
        .expect("spawn terminal");
    assert!(pty.get_session(&session_id).and_then(|session| session.worktree_path()).is_some());
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), None);
    pty.close_session(&session_id).await.expect("close terminal");
    assert!(!pty.has_session(&session_id));

    let mut one_shot = CommandBuilder::new("/bin/sh");
    one_shot.arg("-c");
    one_shot.arg("exit 0");
    one_shot.cwd(&wt);
    let (natural_id, mut output) = pty
        .spawn_in_worktree(one_shot, 80, 24, &manager, &wt)
        .expect("spawn one-shot terminal");

    tokio::time::timeout(Duration::from_secs(5), async {
        while output.recv().await.is_some() {}
    })
    .await
    .expect("natural session output closure");
    assert!(!pty.has_session(&natural_id));
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), None);
}

#[test]
fn pty_spawn_failure_does_not_claim_exclusive_writer() {
    let (_repo, manager) = setup_test_repo();
    let wt = create_worktree(&manager, "pty-spawn-failure");
    let pty = PtyManager::new();

    let mut missing = CommandBuilder::new("/definitely/missing/orca-command");
    missing.cwd(&wt);
    let error = pty
        .spawn_in_worktree(missing, 80, 24, &manager, &wt)
        .expect_err("missing program must fail to spawn");
    assert!(error.to_string().contains("spawn"));
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), None);
}

#[tokio::test]
async fn five_concurrent_worktree_terminal_lifecycles_remain_isolated() {
    let (_repo, manager) = setup_test_repo();
    let pty = PtyManager::new();
    let worktrees = (0..5)
        .map(|index| create_worktree(&manager, &format!("concurrent-{index}")))
        .collect::<Vec<_>>();
    let mut session_ids = Vec::with_capacity(worktrees.len());
    let mut receivers = Vec::with_capacity(worktrees.len());

    for worktree in &worktrees {
        let mut shell = CommandBuilder::new("/bin/sh");
        shell.cwd(worktree);
        let (session_id, receiver) = pty
            .spawn_in_worktree(shell, 80, 24, &manager, worktree)
            .expect("spawn terminal");
        assert_eq!(manager.writer_owner(worktree).expect("writer owner"), None);
        session_ids.push(session_id);
        receivers.push(receiver);
    }

    assert_eq!(pty.session_count(), worktrees.len());

    for session_id in &session_ids {
        pty.close_session(session_id).await.expect("close terminal");
    }

    assert_eq!(pty.session_count(), 0);
    for worktree in &worktrees {
        assert_eq!(manager.writer_owner(worktree).expect("writer owner"), None);
        manager
            .delete_worktree_and_branch(worktree, true)
            .expect("delete clean worktree and merged branch");
    }

    assert_eq!(manager.list_worktrees().expect("remaining worktrees").len(), 1);
    drop(receivers);
}

